from collections import deque
R,C=10,10
seen=set(); comps=[]
for r in range(1,R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and z not in seen and grid[z[0]][z[1]]==color:
      seen.add(z); q.append(z)
   comps.append((color,cells))
[(co, sorted(c)) for co,c in comps]
